package com.booktracker.servlet;
import com.booktracker.dao.TrackerDAO; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException; import java.sql.SQLException;
@WebServlet({"/", "/dashboard"}) public class DashboardServlet extends HttpServlet { private final TrackerDAO dao=new TrackerDAO(); protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{req.setAttribute("books",dao.books());req.setAttribute("borrowers",dao.borrowers());req.setAttribute("issues",dao.issues());req.setAttribute("bookCount",dao.count("books"));req.setAttribute("borrowerCount",dao.count("borrowers"));req.setAttribute("activeCount",dao.issues().stream().filter(i->"ISSUED".equals(i.getStatus())).count());req.getRequestDispatcher("/index.jsp").forward(req,resp);}catch(SQLException e){throw new ServletException("Could not load dashboard. Check database configuration and schema.",e);}} }
